import pytest
from boltons.dictutils import recursive_update

def test_recursive_update_nested_dicts():
    """Test that recursive_update properly merges nested dictionaries"""
    a = {'x': {'y': 1, 'z': 2}}
    b = {'x': {'y': 10, 'w': 3}}
    result = recursive_update(a, b)

    # Should recursively merge nested dicts
    assert result == {'x': {'y': 10, 'z': 2, 'w': 3}}
    assert result['x']['y'] == 10
    assert result['x']['z'] == 2
    assert result['x']['w'] == 3

def test_recursive_update_multiple_levels():
    """Test recursive_update with multiple nesting levels"""
    a = {'a': {'b': {'c': 1}}}
    b = {'a': {'b': {'d': 2}}}
    result = recursive_update(a, b)

    assert result == {'a': {'b': {'c': 1, 'd': 2}}}

def test_recursive_update_overwrite_nondict_with_dict():
    """Test that non-dict values are overwritten by dict values"""
    a = {'x': 'string'}
    b = {'x': {'y': 1}}
    result = recursive_update(a, b)

    assert result == {'x': {'y': 1}}

def test_recursive_update_overwrite_dict_with_nondict():
    """Test that dict values are overwritten by non-dict values"""
    a = {'x': {'y': 1}}
    b = {'x': 'string'}
    result = recursive_update(a, b)

    assert result == {'x': 'string'}

import pytest
from copy import deepcopy
from marshmallow import Schema, fields, pre_load


class InnerSchema(Schema):
    value = fields.String()

    @pre_load(pass_many=False)
    def add_prefix(self, data, **_):
        data = deepcopy(data)
        data['value'] = '_'.join([self.context.get('prefix'), data['value']])
        return data


class MiddleSchema(Schema):
    prefix = fields.String()
    inner = fields.Nested(InnerSchema)

    @pre_load(pass_many=False)
    def store_prefix(self, data, **_):
        self.context['prefix'] = data['prefix']
        return data


class ListNestedSchema(Schema):
    data = fields.List(fields.Nested(MiddleSchema))


class NestedManySchema(Schema):
    data = fields.Nested(MiddleSchema, many=True)


def test_pre_load_hook_order_consistency():
    """Test that List(Nested) and Nested(many=True) execute pre_load hooks in the same order"""
    obj = {'data': [
        {'prefix': 'foo', 'inner': {'value': 'x'}},
        {'prefix': 'bar', 'inner': {'value': 'z'}}
    ]}

    list_nested_result = ListNestedSchema().load(obj)
    nested_many_result = NestedManySchema().load(obj)

    # Both should produce the same result
    # The bug causes NestedManySchema to use the last prefix ('bar') for all items
    assert list_nested_result == nested_many_result

    # Verify the expected correct behavior
    assert list_nested_result['data'][0]['inner']['value'] == 'foo_x'
    assert list_nested_result['data'][1]['inner']['value'] == 'bar_z'

    assert nested_many_result['data'][0]['inner']['value'] == 'foo_x'
    assert nested_many_result['data'][1]['inner']['value'] == 'bar_z'

import pytest
from marshmallow import Schema, fields


class TestDefaultDumpFields:
    """Test for default_dump_fields functionality in Schema"""

    def test_default_dump_fields_basic(self):
        """Test that default_dump_fields limits output fields by default"""

        class MySchema(Schema):
            field_a = fields.Str()
            field_b = fields.Str()
            field_x = fields.Str()
            field_y = fields.Str()
            field_z = fields.Str()

            class Meta:
                default_dump_fields = ['field_a', 'field_b']

        obj = {
            'field_a': 'value_a',
            'field_b': 'value_b',
            'field_x': 'value_x',
            'field_y': 'value_y',
            'field_z': 'value_z',
        }

        # Test 1: Default behavior should only include default_dump_fields
        result = MySchema().dump(obj)
        assert set(result.keys()) == {'field_a', 'field_b'}
        assert result == {'field_a': 'value_a', 'field_b': 'value_b'}

        # Test 2: Include additional fields beyond defaults
        result = MySchema(include=['field_x', 'field_y']).dump(obj)
        assert set(result.keys()) == {'field_a', 'field_b', 'field_x', 'field_y'}

        # Test 3: Override with only parameter should ignore default_dump_fields
        result = MySchema(only=['field_a']).dump(obj)
        assert set(result.keys()) == {'field_a'}

        # Test 4: Explicitly setting only=None or empty should respect defaults
        result = MySchema().dump(obj)
        assert set(result.keys()) == {'field_a', 'field_b'}

import pytest
import marshmallow as ma


def test_hook_name_validation():
    """Test that hook methods must be named correctly with _h suffix"""

    # This should raise ValueError because method name doesn't match hook_name
    with pytest.raises(ValueError, match="post_load_h hook had incorrect name"):
        class A(ma.Schema):
            foo = ma.fields.Str()

            @ma.post_load
            def wrong_name(self, data, **kwargs):
                return {"bar": 1, **data}


def test_hook_name_validation_correct_name():
    """Test that correctly named hook methods work"""

    class A(ma.Schema):
        foo = ma.fields.Str()

        @ma.post_load
        def post_load_h(self, data, **kwargs):
            return {"bar": 1, **data}

    result = A().load({"foo": "baz"})
    assert result == {"bar": 1, "foo": "baz"}


def test_hook_inheritance_with_super():
    """Test that hook methods can be overridden in subclasses using super()"""

    class A(ma.Schema):
        foo = ma.fields.Str()

        @ma.post_load
        def post_load_h(self, data, **kwargs):
            return {"bar": 1, **data}

    class B(A):
        @ma.post_load
        def post_load_h(self, data, **kwargs):
            d = super().post_load_h(data, **kwargs)
            del d["foo"]
            return d

    class C(B):
        @ma.post_load
        def post_load_h(self, data, **kwargs):
            data["save"] = dict(data)
            return super().post_load_h(data, **kwargs)

    assert A().load({"foo": "baz"}) == {"bar": 1, "foo": "baz"}
    assert B().load({"foo": "baz"}) == {"bar": 1}
    assert C().load({"foo": "baz"}) == {"bar": 1, "save": {"foo": "baz"}}

