from marshmallow import Schema, fields


def test_function_field_default_deserialization():
    """Test that Function field without deserialize parameter passes value through unchanged."""

    class Foo(Schema):
        baz = fields.Function(serialize=lambda x: x['bar']['baz'])
        qux = fields.Function(serialize=lambda x: x['bar']['qux'])

        @marshmallow.post_load
        def post_load(self, data, many, **kwargs):
            return {'bar': data}

    s = {'baz': 'blue', 'qux': 'orange'}

    # This should not raise ValidationError
    d = Foo().load(s)

    # Verify the result structure
    assert d == {'bar': {'baz': 'blue', 'qux': 'orange'}}

    # Verify serialization works
    result = Foo().dump(d)
    assert result == {'baz': 'blue', 'qux': 'orange'}

