import pytest
from marshmallow import Schema, fields, ValidationError


class OneOfSchema(Schema):
    """OneOfSchema implementation that uses _deserialize and _serialize hooks"""
    oneof = {}
    discriminator = None

    def discriminate_on_load(self, data):
        if isinstance(data, dict) and self.discriminator in data:
            schema_name = data[self.discriminator]
            if schema_name in self.oneof:
                return self.oneof[schema_name]
        raise ValidationError(f"Cannot determine schema for {data}")

    def discriminate_on_dump(self, obj, **kwargs):
        if isinstance(obj, dict) and self.discriminator in obj:
            schema_name = obj[self.discriminator]
            if schema_name in self.oneof:
                return self.oneof[schema_name]
        raise ValidationError(f"Cannot determine schema for {obj}")

    def _deserialize(self, data, attr, obj, **kwargs):
        schema = self.discriminate_on_load(data)
        return schema().load(data)

    def _serialize(self, value, attr, obj, **kwargs):
        schema = self.discriminate_on_dump(value)
        return schema().dump(value)


class DogSchema(Schema):
    pet_type = fields.Constant("dog")
    name = fields.Str()
    bark = fields.Str()


class CatSchema(Schema):
    pet_type = fields.Constant("cat")
    name = fields.Str()
    meow = fields.Str()


class PetSchema(OneOfSchema):
    oneof = {"dog": DogSchema, "cat": CatSchema}
    discriminator = "pet_type"


def test_oneof_schema_with_hooks():
    """Test that OneOfSchema properly invokes pre/post load hooks"""
    hook_called = []

    class CustomDogSchema(DogSchema):
        @fields.pre_load
        def process_input(self, data, **kwargs):
            hook_called.append("pre_load")
            return data

        @fields.post_load
        def process_output(self, data, **kwargs):
            hook_called.append("post_load")
            return data

    class CustomPetSchema(OneOfSchema):
        oneof = {"dog": CustomDogSchema, "cat": CatSchema}
        discriminator = "pet_type"

    schema = CustomPetSchema()
    data = {"pet_type": "dog", "name": "Buddy", "bark": "Woof"}

    hook_called.clear()
    result = schema.load(data)

    # Hooks should be called when using _deserialize instead of overriding load
    assert "pre_load" in hook_called, "pre_load hook was not called"
    assert "post_load" in hook_called, "post_load hook was not called"
    assert result["name"] == "Buddy"

