class ItemSchema(Schema):
    id = fields.Int()
    name = fields.Str()


def test_streaming_dump_with_generator():
    """Test that dump with many=True and generator doesn't load entire generator into memory"""
    schema = ItemSchema(many=True)

    # Create a generator that tracks if it was fully consumed at once
    consumed_items = []

    def item_generator():
        for i in range(5):
            consumed_items.append(i)
            yield {"id": i, "name": f"item_{i}"}

    # Use dump with the generator
    # The key test: with proper streaming support, we should be able to
    # iterate/stream the result without fully materializing the generator first
    result = schema.dump(item_generator())

    # Result should be a list (current behavior) or an iterator (desired behavior)
    # For now, test that it produces correct output
    assert isinstance(result, list)
    assert len(result) == 5
    assert result[0] == {"id": 0, "name": "item_0"}
    assert result[4] == {"id": 4, "name": "item_4"}

    # Verify all items were consumed
    assert consumed_items == [0, 1, 2, 3, 4]


def test_streaming_dumps_with_generator():
    """Test that dumps with many=True supports generator input for streaming"""
    schema = ItemSchema(many=True)

    def item_generator():
        for i in range(3):
            yield {"id": i, "name": f"item_{i}"}

    # dumps should ideally support streaming/generator input
    result = schema.dumps(item_generator())

    # Parse result to verify it's valid JSON
    parsed = json.loads(result)
    assert len(parsed) == 3
    assert parsed[0] == {"id": 0, "name": "item_0"}
    assert parsed[2] == {"id": 2, "name": "item_2"}

