def test_dotted_only_with_nested_tuple():
    """Test that dotted 'only' notation works with nested fields in Tuples"""

    class Child(Schema):
        name = fields.String()
        age = fields.Integer()

    class Friend(Schema):
        name = fields.String()
        height = fields.Integer()

    class Family(Schema):
        kidsandfriends = fields.Tuple((fields.Nested(Child), fields.Nested(Friend)))

    data = {
        'kidsandfriends': (
            {"name": "steve", "age": 0},
            {"name": "john", "height": 2}
        )
    }

    result = Family(only=['kidsandfriends.name']).dump(data)

    # Expected: only 'name' field should be present in both tuple elements
    expected = {
        'kidsandfriends': (
            {'name': 'steve'},
            {'name': 'john'}
        )
    }

    assert result == expected, f"Expected {expected}, but got {result}"

