import pytest
from marshmallow import Schema, fields


def test_dump_iteration_override():
    """Test that dump iteration behavior can be overridden."""

    class CustomIterableSchema(Schema):
        items = fields.List(fields.String())

        def _dump_iteration(self, obj):
            """Override dump iteration to reverse order."""
            if hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes)):
                return reversed(list(obj))
            return [obj]

    class ItemSchema(Schema):
        name = fields.String()
        values = fields.List(fields.Integer())

    schema = ItemSchema()

    # Custom schema that overrides iteration behavior
    class ReversedListSchema(Schema):
        items = fields.List(fields.String())

        def _dump_iteration(self, obj):
            """Return reversed iterator for lists."""
            if isinstance(obj, list):
                return iter(reversed(obj))
            return iter(obj)

    reverse_schema = ReversedListSchema()

    # Test with normal schema - should maintain order
    normal_data = {"items": ["a", "b", "c"]}
    normal_result = schema.dump({"items": ["a", "b", "c"]})

    # Test with custom iteration schema - should reverse order
    reversed_result = reverse_schema.dump({"items": ["a", "b", "c"]})

    # Verify override works
    assert hasattr(reverse_schema, '_dump_iteration'), "Schema should support _dump_iteration override"
    assert callable(reverse_schema._dump_iteration), "_dump_iteration should be callable"

